cards.solution:
public class Main {
    public static void main(String[] args) {
        int a = 8;
        int b = 0;
        try {
            System.out.println(a / b);
        } catch (ArithmeticException e) {
            System.out.println("Error: pembagian nol");
        }
        System.out.println("Selesai");
    }
}

